function validate([s]) {
  if (typeof s !== 'string' || s.length < 1 || s.length > 10000) return 's needs 1 to 10^4 characters.';
  if (!/^[01]+$/.test(s)) return "s may contain only '0' and '1'.";
  return null;
}

