function minOperations(s) {
  // Try every set of positions to flip and keep the smallest that alternates.
  const n = s.length;
  let best = Infinity;
  for (let mask = 0; mask < (1 << n); mask++) {
    const chars = s.split('').map((c, i) => (mask >> i) & 1 ? (c === '0' ? '1' : '0') : c);
    let alternating = true;
    for (let i = 1; i < n; i++) if (chars[i] === chars[i - 1]) alternating = false;
    if (alternating) {
      let flips = 0;
      for (let m = mask; m; m >>= 1) flips += m & 1;
      best = Math.min(best, flips);
    }
  }
  return best;
}

