function generate(rand, size) {
  const n = size === 'large' ? 10000 : 1 + Math.floor(rand() * 10);
  const mode = rand();
  let chars;
  if (mode < 0.4) {
    chars = Array.from({ length: n }, () => (rand() < 0.5 ? '0' : '1'));
  } else {
    // Start from an alternating string and flip a few positions.
    const first = rand() < 0.5 ? 0 : 1;
    chars = Array.from({ length: n }, (_, i) => String((i + first) % 2));
    const flips = Math.floor(rand() * (size === 'large' ? 6000 : n + 1));
    for (let f = 0; f < flips; f++) {
      const i = Math.floor(rand() * n);
      chars[i] = chars[i] === '0' ? '1' : '0';
    }
  }
  return [chars.join('')];
}
